insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','연구위원급(선임급 포함) 요청사항 Top 20','<div class="box" style="margin-bottom:16px"><b>게시판 분석 자료</b> · 작성자 관리자 · 게시일 2026-09-12<br><a href="https://grilu.kr/archive/documents/report-demands.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문 전문 보기</a></div><p style="line-height:1.8;color:#444"> 홈페이지 게시판(노사협의회 공고·회의록 73건, 단체교섭·단체협약 10건, 심의위원회 19건, 노동이사 활동보고 14건, 행정사무감사 회의록 31건)에 실린 노측 건의·요구 사항을 직군별로 모아 정리했습니다. 빈도(반복 제기 횟수)와 최근성(2023년 이후 협의회 안건)을 우선해 순위를 매겼습니다. 오른쪽 열의  건수/횟수 는 게시판 전체 자료(본문+첨부 전문)에서 해당 주제가 언급된 글 수와 문장 수이며, 대표 자료를 누르면 해당 문장이 형광 표시된 원문이 열립니다.  연구위원급(선임연구위원·연구위원, 박사급) 요청사항 Top 20     순위  요구사항  근거(게시판 자료) · 언급 횟수 · 대표 회의자료      1  연구직 평가제도(근무성적평정) 개선 — 정성평가 반영, 역량평가 비중 조정, 사전 설명회  2011 2분기 안건, 2014 2차 협의회, 2024 1·2차 협의회  33건 의 자료에서  282회  언급  대표 자료:   2025.11 25-10차 심의위원회 상정(안) 게시 및 직원…   (82회)  ·  2024.08 24-10차 심의위원회 상정(안) 게시 및 직원…   (55회)  ·  2024.06 24-7차 심의위원회 상정(안) 게…</p>','관리자',false,'{"legacy_id": "gw-report-demands", "page": "archive/documents/report-demands.html", "files": [], "source": "게시판 분석"}'::jsonb,'2026-09-12'::date,'2026-09-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-report-demands');
