insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','연구원급(공무직군) 요청사항 Top 20','<div class="box" style="margin-bottom:16px"><b>게시판 분석 자료</b> · 작성자 관리자 · 게시일 2026-09-12<br><a href="https://grilu.kr/archive/documents/report-demands-res.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문 전문 보기</a></div><p style="line-height:1.8;color:#444"> 홈페이지 게시판(노사협의회 공고·회의록 73건, 단체교섭·단체협약 10건, 심의위원회 19건, 노동이사 활동보고 14건, 행정사무감사 회의록 31건)에 실린 노측 건의·요구 사항을 직군별로 모아 정리했습니다. 빈도(반복 제기 횟수)와 최근성(2023년 이후 협의회 안건)을 우선해 순위를 매겼습니다. 오른쪽 열의  건수/횟수 는 게시판 전체 자료(본문+첨부 전문)에서 해당 주제가 언급된 글 수와 문장 수이며, 대표 자료를 누르면 해당 문장이 형광 표시된 원문이 열립니다.  연구원급(공무직군: 연구원·선임연구원·행정직) 요청사항 Top 20     순위  요구사항  근거(게시판 자료) · 언급 횟수 · 대표 회의자료      1  공무직(연구원) 직급체계 개선 — 연구원(가·나급)·선임연구원 등 승진 경로 신설  2024.10 3차 협의회, 2025.6 2차 협의회 &#x27;직급체계·보수체계 개선 필요성 공감, 지속 논의&#x27;  6건 의 자료에서  18회  언급  대표 자료:   2024.10 2024년도 제3차 노사협의회 결과 및 회의록   (7회)  ·  2026.01 2025년 하반기 경기연구원 노동이사 활동 보고   (4회)  ·  2025.06 2025년 제2차…</p>','관리자',false,'{"legacy_id": "gw-report-demands-res", "page": "archive/documents/report-demands-res.html", "files": [], "source": "게시판 분석"}'::jsonb,'2026-09-12'::date,'2026-09-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-report-demands-res');
